"""Placement predicates, node selection and preemption.

Predicates are pure functions returning `(ok, reason)`: a rejection that cannot say why is useless
when a schedule looks wrong, so every branch names the constraint it hit. Node selection is
deterministic -- ties always break on node id -- and preemption picks the *smallest* set of the
lowest-priority tasks that makes the incoming task fit.
"""

from __future__ import annotations

from dataclasses import dataclass

from .errors import ValidationError
from .model import Cluster, Node, Placement, Resources, Task

POLICIES = ("first-fit", "best-fit")


@dataclass(frozen=True, slots=True)
class Decision:
    task_id: str
    node_id: str | None
    reason: str
    preempted: tuple[str, ...] = ()

    def to_document(self) -> dict[str, object]:
        document: dict[str, object] = {"task": self.task_id, "reason": self.reason}
        if self.node_id is not None:
            document["node"] = self.node_id
        if self.preempted:
            document["preempted"] = list(self.preempted)
        return document


def capacity_predicate(task: Task, free: Resources) -> tuple[bool, str]:
    if not task.request.fits(free):
        return False, f"insufficient capacity: needs cpu={task.request.cpu},memory={task.request.memory} has cpu={free.cpu},memory={free.memory}"
    return True, "capacity ok"


def affinity_predicate(task: Task, node: Node) -> tuple[bool, str]:
    labels = node.label_map()
    for key, value in task.affinity:
        if labels.get(key) != value:
            return False, f"affinity {key}={value} not satisfied (node has {key}={labels.get(key)!r})"
    for key in task.anti_affinity:
        if key in labels:
            return False, f"anti-affinity: node carries label {key}"
    return True, "affinity ok"


def taint_predicate(task: Task, node: Node) -> tuple[bool, str]:
    for taint in node.taints:
        if taint not in task.tolerations:
            return False, f"untolerated taint {taint}"
    return True, "taints ok"


PREDICATES = (capacity_predicate, affinity_predicate, taint_predicate)


def fits(cluster: Cluster, task: Task, node: Node) -> tuple[bool, str]:
    """All predicates, reported in a stable order so the first failure is always the same one."""
    free = cluster.free(node.id)
    ok, reason = capacity_predicate(task, free)
    if not ok:
        return False, reason
    ok, reason = affinity_predicate(task, node)
    if not ok:
        return False, reason
    return taint_predicate(task, node)


def order_candidates(cluster: Cluster, policy: str) -> list[Node]:
    if policy not in POLICIES:
        raise ValidationError(f"policy must be one of {', '.join(POLICIES)}", value=policy)
    nodes = sorted(cluster.nodes, key=lambda node: node.id)
    if policy == "first-fit":
        return nodes
    # best-fit: smallest remaining CPU, then smallest remaining memory, then node id for determinism
    return sorted(nodes, key=lambda node: (cluster.free(node.id).cpu, cluster.free(node.id).memory, node.id))


def select_node(cluster: Cluster, task: Task, policy: str = "first-fit") -> Decision:
    """The first candidate that passes every predicate, in the order the policy defines."""
    reasons: list[str] = []
    for node in order_candidates(cluster, policy):
        ok, reason = fits(cluster, task, node)
        if ok:
            return Decision(task.id, node.id, f"placed by {policy}")
        reasons.append(f"{node.id}: {reason}")
    detail = "; ".join(reasons) if reasons else "no nodes in the cluster"
    return Decision(task.id, None, f"no node fits ({detail})")


def running_on(placements: list[Placement], tasks: dict[str, Task], node_id: str, now: int) -> list[Placement]:
    return [item for item in placements if item.node_id == node_id and item.start <= now < item.end and item.task_id in tasks]


def preemption_candidates(
    cluster: Cluster,
    task: Task,
    node: Node,
    placements: list[Placement],
    tasks: dict[str, Task],
    now: int,
) -> tuple[list[Placement], str]:
    """The smallest set of lower-priority running tasks whose eviction frees room for `task`.

    Candidates are ordered lowest priority first, then largest request, then task id, and the search
    stops as soon as the request fits -- so the answer is deterministic and is never larger than needed.
    A task is never a candidate for eviction of something at its own priority or higher.
    """
    if task.priority <= 0:
        return [], "preemption only applies to positive priorities"
    clock_free = cluster.free(node.id)
    if task.request.fits(clock_free):
        return [], "no preemption needed"
    candidates = [item for item in running_on(placements, tasks, node.id, now) if tasks[item.task_id].priority < task.priority]
    candidates.sort(key=lambda item: (tasks[item.task_id].priority, -tasks[item.task_id].request.cpu, -tasks[item.task_id].request.memory, item.task_id))
    freed = clock_free
    chosen: list[Placement] = []
    for candidate in candidates:
        chosen.append(candidate)
        freed = freed.plus(tasks[candidate.task_id].request)
        if task.request.fits(freed):
            return chosen, f"preempting {len(chosen)} lower-priority task(s) on {node.id}"
    return [], f"even evicting every lower-priority task on {node.id} would not fit cpu={task.request.cpu},memory={task.request.memory}"


def fragmentation(cluster: Cluster, tasks: dict[str, Task]) -> dict[str, int]:
    """How many nodes could not accept the smallest pending task, and their wasted CPU."""
    if not tasks:
        return {"nodesBlocked": 0, "wastedCpu": 0}
    smallest = min(tasks.values(), key=lambda item: (item.request.cpu, item.request.memory, item.id)).request
    blocked = 0
    wasted = 0
    for node in cluster.nodes:
        free = cluster.free(node.id)
        if not smallest.fits(free):
            blocked += 1
            wasted += free.cpu
    return {"nodesBlocked": blocked, "wastedCpu": wasted}

"""Resource model: capacities, requests, nodes, tasks and placements.

Everything is integer arithmetic on CPU units and memory units. Tasks and nodes are validated at
construction, so the simulator never has to defend against negative requests halfway through a run.
"""

from __future__ import annotations

from dataclasses import dataclass, field

from .errors import ValidationError


@dataclass(frozen=True, slots=True)
class Resources:
    cpu: int
    memory: int

    def __post_init__(self) -> None:
        if self.cpu < 0 or self.memory < 0:
            raise ValidationError("resources must be non-negative", cpu=self.cpu, memory=self.memory)

    def fits(self, available: "Resources") -> bool:
        return self.cpu <= available.cpu and self.memory <= available.memory

    def plus(self, other: "Resources") -> "Resources":
        return Resources(self.cpu + other.cpu, self.memory + other.memory)

    def minus(self, other: "Resources") -> "Resources":
        return Resources(max(0, self.cpu - other.cpu), max(0, self.memory - other.memory))

    def to_document(self) -> dict[str, int]:
        return {"cpu": self.cpu, "memory": self.memory}


@dataclass(frozen=True, slots=True)
class Task:
    id: str
    request: Resources
    priority: int = 0
    queue: str = "default"
    arrival: int = 0
    duration: int = 1
    affinity: tuple[tuple[str, str], ...] = ()
    anti_affinity: tuple[str, ...] = ()
    tolerations: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not self.id:
            raise ValidationError("task id must be non-empty")
        if self.duration <= 0:
            raise ValidationError("duration must be > 0", task=self.id, value=self.duration)
        if self.arrival < 0:
            raise ValidationError("arrival must be >= 0", task=self.id, value=self.arrival)
        if self.request.cpu == 0 and self.request.memory == 0:
            raise ValidationError("a task must request something", task=self.id)

    def affinity_map(self) -> dict[str, str]:
        return dict(self.affinity)

    def to_document(self) -> dict[str, object]:
        return {
            "id": self.id,
            "queue": self.queue,
            "priority": self.priority,
            "arrival": self.arrival,
            "duration": self.duration,
            "request": self.request.to_document(),
            "affinity": dict(self.affinity),
            "antiAffinity": list(self.anti_affinity),
            "tolerations": list(self.tolerations),
        }


@dataclass(frozen=True, slots=True)
class Node:
    id: str
    capacity: Resources
    labels: tuple[tuple[str, str], ...] = ()
    taints: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not self.id:
            raise ValidationError("node id must be non-empty")

    def label_map(self) -> dict[str, str]:
        return dict(self.labels)

    def to_document(self) -> dict[str, object]:
        return {
            "id": self.id,
            "capacity": self.capacity.to_document(),
            "labels": dict(self.labels),
            "taints": list(self.taints),
        }


@dataclass(frozen=True, slots=True)
class Placement:
    task_id: str
    node_id: str
    start: int
    end: int
    preempted: tuple[str, ...] = ()

    def to_document(self) -> dict[str, object]:
        document: dict[str, object] = {"task": self.task_id, "node": self.node_id, "start": self.start, "end": self.end}
        if self.preempted:
            document["preempted"] = list(self.preempted)
        return document


@dataclass(slots=True)
class Cluster:
    nodes: tuple[Node, ...]
    _used: dict[str, Resources] = field(default_factory=dict, init=False)

    def __post_init__(self) -> None:
        ids = [node.id for node in self.nodes]
        if len(set(ids)) != len(ids):
            raise ValidationError("node ids must be unique", ids=ids)
        for node in self.nodes:
            self._used[node.id] = Resources(0, 0)

    def node(self, node_id: str) -> Node:
        for node in self.nodes:
            if node.id == node_id:
                return node
        raise ValidationError(f"unknown node: {node_id}", known=[node.id for node in self.nodes])

    def used(self, node_id: str) -> Resources:
        self.node(node_id)
        return self._used[node_id]

    def free(self, node_id: str) -> Resources:
        return self.node(node_id).capacity.minus(self.used(node_id))

    def occupy(self, node_id: str, resources: Resources) -> None:
        self.node(node_id)
        self._used[node_id] = self._used[node_id].plus(resources)

    def release(self, node_id: str, resources: Resources) -> None:
        self.node(node_id)
        self._used[node_id] = self._used[node_id].minus(resources)

    def total_capacity(self) -> Resources:
        total = Resources(0, 0)
        for node in self.nodes:
            total = total.plus(node.capacity)
        return total

    def total_used(self) -> Resources:
        total = Resources(0, 0)
        for node in self.nodes:
            total = total.plus(self._used[node.id])
        return total

"""Command line entry point.

A cluster is a JSONL node list; a task set is a JSONL task list. Both are validated with line numbers,
so a bad request says exactly where it went wrong. Every subcommand writes one JSON document to stdout;
errors are one JSON document on stderr. Exit codes: 0 success, 2 input/usage error, 3 a report whose
verdict is negative (tasks left unplaced, or two runs that disagreed).
"""

from __future__ import annotations

import argparse
import json
import sys
from typing import Any, Sequence

from . import __version__
from .errors import ParseError, SchedulerError, ValidationError
from .model import Node, Resources, Task
from .policies import POLICIES
from .simulator import Simulation, compare_policies, replay, simulate

EXIT_OK = 0
EXIT_ERROR = 2
EXIT_NEGATIVE = 3


def canonical(document: dict[str, Any]) -> str:
    return json.dumps(document, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def _emit(document: dict[str, Any]) -> None:
    sys.stdout.write(canonical(document) + "\n")


def _read_lines(path: str) -> list[str]:
    if path == "-":
        return sys.stdin.read().splitlines()
    try:
        with open(path, encoding="utf-8") as handle:
            return handle.read().splitlines()
    except OSError as error:
        raise ValidationError(f"cannot read input: {error.strerror or error}", value=path) from error


def _rows(path: str, what: str) -> list[tuple[int, dict[str, Any]]]:
    rows: list[tuple[int, dict[str, Any]]] = []
    for number, text in enumerate(_read_lines(path), start=1):
        stripped = text.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            document = json.loads(stripped)
        except json.JSONDecodeError as error:
            raise ParseError(f"{what} line {number}: invalid JSON: {error.msg}", line=number) from error
        if not isinstance(document, dict):
            raise ParseError(f"{what} line {number}: expected a JSON object", line=number)
        rows.append((number, document))
    return rows


def _pairs(document: dict[str, Any], key: str, number: int, what: str) -> tuple[tuple[str, str], ...]:
    value = document.get(key, {})
    if value in (None, {}):
        return ()
    if not isinstance(value, dict):
        raise ParseError(f"{what} line {number}: {key} must be an object", line=number)
    return tuple(sorted((str(item), str(target)) for item, target in value.items()))


def _strings(document: dict[str, Any], key: str, number: int, what: str) -> tuple[str, ...]:
    value = document.get(key, [])
    if value in (None, []):
        return ()
    if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
        raise ParseError(f"{what} line {number}: {key} must be a list of strings", line=number)
    return tuple(sorted(str(item) for item in value))


def _resources(document: dict[str, Any], number: int, what: str) -> Resources:
    cpu = document.get("cpu", 0)
    memory = document.get("memory", 0)
    for name, value in (("cpu", cpu), ("memory", memory)):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ParseError(f"{what} line {number}: {name} must be an integer", line=number)
    return Resources(cpu, memory)


def load_cluster(path: str) -> tuple[Node, ...]:
    nodes: list[Node] = []
    for number, document in _rows(path, "cluster"):
        unknown = sorted(set(document) - {"id", "cpu", "memory", "labels", "taints"})
        if unknown:
            raise ParseError(f"cluster line {number}: unknown field(s): {', '.join(unknown)}", line=number)
        if "id" not in document:
            raise ParseError(f"cluster line {number}: missing id", line=number)
        nodes.append(
            Node(
                id=str(document["id"]),
                capacity=_resources(document, number, "cluster"),
                labels=_pairs(document, "labels", number, "cluster"),
                taints=_strings(document, "taints", number, "cluster"),
            )
        )
    if not nodes:
        raise ValidationError("the cluster is empty")
    return tuple(nodes)


def load_tasks(path: str) -> tuple[Task, ...]:
    tasks: list[Task] = []
    known = {"id", "cpu", "memory", "priority", "queue", "arrival", "duration", "affinity", "antiAffinity", "tolerations"}
    for number, document in _rows(path, "task"):
        unknown = sorted(set(document) - known)
        if unknown:
            raise ParseError(f"task line {number}: unknown field(s): {', '.join(unknown)}", line=number)
        if "id" not in document:
            raise ParseError(f"task line {number}: missing id", line=number)
        for name in ("priority", "arrival", "duration"):
            value = document.get(name)
            if value is not None and (isinstance(value, bool) or not isinstance(value, int)):
                raise ParseError(f"task line {number}: {name} must be an integer", line=number)
        tasks.append(
            Task(
                id=str(document["id"]),
                request=_resources(document, number, "task"),
                priority=int(document.get("priority", 0)),
                queue=str(document.get("queue", "default")),
                arrival=int(document.get("arrival", 0)),
                duration=int(document.get("duration", 1)),
                affinity=_pairs(document, "affinity", number, "task"),
                anti_affinity=_strings(document, "antiAffinity", number, "task"),
                tolerations=_strings(document, "tolerations", number, "task"),
            )
        )
    if not tasks:
        raise ValidationError("the task set is empty")
    return tuple(tasks)


def load_queue_weights(path: str) -> dict[str, int]:
    """Parse the optional JSONL ``{"queue": ..., "weight": ...}`` file.

    Shape problems -- broken JSON, a non-object row, missing fields, wrong types, unknown fields --
    are parse errors naming the raw line. Semantic problems -- a non-positive weight or a queue
    declared twice -- are validation errors. A file with no valid rows is rejected rather than
    silently treated as "no config" (which would run the baseline instead of the requested mode).
    """
    weights: dict[str, int] = {}
    for number, document in _rows(path, "queue weights"):
        unknown = sorted(set(document) - {"queue", "weight"})
        if unknown:
            raise ParseError(f"queue weights line {number}: unknown field(s): {', '.join(unknown)}", line=number)
        if "queue" not in document:
            raise ParseError(f"queue weights line {number}: missing queue", line=number)
        if "weight" not in document:
            raise ParseError(f"queue weights line {number}: missing weight", line=number)
        queue = document["queue"]
        weight = document["weight"]
        if not isinstance(queue, str) or not queue:
            raise ParseError(f"queue weights line {number}: queue must be a non-empty string", line=number)
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise ParseError(f"queue weights line {number}: weight must be an integer", line=number)
        if weight <= 0:
            raise ValidationError(
                f"queue weights line {number}: weight must be positive", line=number, queue=queue, value=weight
            )
        if queue in weights:
            raise ValidationError(
                f"queue weights line {number}: duplicate queue {queue!r}", line=number, queue=queue
            )
        weights[queue] = weight
    if not weights:
        raise ValidationError("the queue weights file is empty", value=path)
    return weights


def _options(args: argparse.Namespace) -> dict[str, object]:
    options: dict[str, object] = {
        "policy": args.policy,
        "allow_preemption": args.preemption,
        "backfill": not args.no_backfill,
    }
    path = getattr(args, "queue_weights", None)
    if path:
        options["queue_weights"] = load_queue_weights(path)
    return options


# -- commands ------------------------------------------------------------------------------------
def _command_describe(_: argparse.Namespace) -> int:
    _emit(
        {
            "name": "cluster-scheduler-simulator",
            "version": __version__,
            "subcommands": ["describe", "metrics", "policies", "replay", "simulate", "trace", "validate"],
            "policies": list(POLICIES),
            "clusterFields": ["id", "cpu", "memory", "labels", "taints"],
            "taskFields": [
                "id",
                "cpu",
                "memory",
                "priority",
                "queue",
                "arrival",
                "duration",
                "affinity",
                "antiAffinity",
                "tolerations",
            ],
            "deterministic": "no wall clock, no set iteration, ties always break on id",
            "exitCodes": {"ok": EXIT_OK, "error": EXIT_ERROR, "negativeVerdict": EXIT_NEGATIVE},
        }
    )
    return EXIT_OK


def _command_validate(args: argparse.Namespace) -> int:
    nodes = load_cluster(args.cluster)
    tasks = load_tasks(args.tasks)
    # Constructing the simulation *is* the validation: `Cluster` catches duplicate node ids and
    # `Simulation` catches duplicate task ids. It takes no options on purpose -- `validate` checks the
    # inputs, and the policy is already constrained by argparse. (Reading `_options(args)` here crashed:
    # the validate subparser has no policy flags, which the test suite caught immediately.)
    Simulation(nodes=nodes, tasks=tasks)
    _emit(
        {
            "nodes": len(nodes),
            "tasks": len(tasks),
            "totalCapacity": _total_capacity(nodes),
            "requested": _total_requested(tasks),
        }
    )
    return EXIT_OK


def _total_capacity(nodes: tuple[Node, ...]) -> dict[str, int]:
    cpu = sum(node.capacity.cpu for node in nodes)
    memory = sum(node.capacity.memory for node in nodes)
    return {"cpu": cpu, "memory": memory}


def _total_requested(tasks: tuple[Task, ...]) -> dict[str, int]:
    cpu = sum(task.request.cpu for task in tasks)
    memory = sum(task.request.memory for task in tasks)
    return {"cpu": cpu, "memory": memory}


def _command_simulate(args: argparse.Namespace) -> int:
    result = simulate(load_cluster(args.cluster), load_tasks(args.tasks), **_options(args))
    _emit(result.to_document())
    return EXIT_OK if not result.unplaced else EXIT_NEGATIVE


def _command_trace(args: argparse.Namespace) -> int:
    result = simulate(load_cluster(args.cluster), load_tasks(args.tasks), **_options(args))
    _emit(
        {
            "policy": result.policy,
            "makespan": result.makespan,
            "decisions": result.decisions,
            "unplaced": result.unplaced,
        }
    )
    return EXIT_OK if not result.unplaced else EXIT_NEGATIVE


def _command_metrics(args: argparse.Namespace) -> int:
    result = simulate(load_cluster(args.cluster), load_tasks(args.tasks), **_options(args))
    _emit({"policy": result.policy, "metrics": result.metrics})
    return EXIT_OK if not result.unplaced else EXIT_NEGATIVE


def _command_policies(args: argparse.Namespace) -> int:
    report = compare_policies(load_cluster(args.cluster), load_tasks(args.tasks), **{k: v for k, v in _options(args).items() if k != "policy"})
    _emit(report)
    best = min(report["policies"], key=lambda entry: (entry["unplaced"], entry["makespan"], entry["policy"]))
    return EXIT_OK if best["unplaced"] == 0 else EXIT_NEGATIVE


def _command_replay(args: argparse.Namespace) -> int:
    report = replay(load_cluster(args.cluster), load_tasks(args.tasks), **_options(args))
    _emit(report)
    return EXIT_OK if report["identical"] else EXIT_NEGATIVE


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="cluster-scheduler-simulator", description="deterministic cluster scheduling simulation")
    parser.add_argument("--version", action="version", version=f"cluster-scheduler-simulator {__version__}")
    subparsers = parser.add_subparsers(dest="command", required=True)

    subparsers.add_parser("describe", help="print capabilities as JSON").set_defaults(handler=_command_describe)

    def with_inputs(name: str, help_text: str) -> argparse.ArgumentParser:
        sub = subparsers.add_parser(name, help=help_text)
        sub.add_argument("--cluster", required=True, help="JSONL nodes, or - for stdin")
        sub.add_argument("--tasks", required=True, help="JSONL tasks")
        return sub

    def with_options(sub: argparse.ArgumentParser) -> argparse.ArgumentParser:
        sub.add_argument("--policy", choices=list(POLICIES), default="first-fit")
        sub.add_argument("--preemption", action="store_true", help="allow higher priorities to evict lower ones")
        sub.add_argument("--no-backfill", action="store_true", help="disable conservative backfill")
        sub.add_argument(
            "--queue-weights",
            metavar="PATH",
            help="JSONL {queue, weight} rows; enables weighted fair-share scheduling",
        )
        return sub

    with_inputs("validate", "parse and validate both inputs").set_defaults(handler=_command_validate)
    with_options(with_inputs("simulate", "run the simulation")).set_defaults(handler=_command_simulate)
    with_options(with_inputs("trace", "per-decision scheduling trace")).set_defaults(handler=_command_trace)
    with_options(with_inputs("metrics", "metrics only")).set_defaults(handler=_command_metrics)
    with_options(with_inputs("replay", "run twice and check the traces match")).set_defaults(handler=_command_replay)
    with_options(with_inputs("policies", "compare first-fit and best-fit")).set_defaults(handler=_command_policies)
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        return int(args.handler(args))
    except SchedulerError as error:
        sys.stderr.write(canonical(error.to_document()) + "\n")
        return EXIT_ERROR


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())

